import csv
import boto3
from moto import mock_aws

@mock_aws
def send_sns_alert():
    # 1. Try reading the report generated by tracker.py first
    try:
        with open("aws_report.csv", mode="r") as file:
            rows = list(csv.reader(file))[1:]  # Skip header row
    except FileNotFoundError:
        print("Error: aws_report.csv not found. Please run 'python tracker.py' first.")
        return

    # 2. Connect to simulated SNS and create an alert channel
    sns = boto3.client("sns", region_name="ap-south-1")
    topic = sns.create_topic(Name="aws-resource-alerts")
    topic_arn = topic["TopicArn"]

    # 3. Format and publish the alert message
    message = f"Daily Scan Complete: {len(rows)} active AWS resources found.\n"
    for row in rows:
        message += f"- {row[0]}: {row[1]} ({row[2]})\n"

    response = sns.publish(
        TopicArn=topic_arn,
        Subject="AWS Resource Tracker Alert",
        Message=message
    )
    print("Alert published! Message ID:", response["MessageId"])
    print("\n--- Sent Message ---\n" + message)

if __name__ == "__main__":
    send_sns_alert()